import { startCloud, signInCloud, signOutCloud, saveCloud } from './cloud.js?v=7';

(() => {
  'use strict';
  const KEY='my-investment-account-v1';
  const META={gold:{name:'Gold',icon:'🥇',class:'gold-bg',desc:'A precious metal'},usa:{name:'US Shares',icon:'🇺🇸',class:'usa-bg',desc:'Large American companies'},asia:{name:'Asia Shares',icon:'🌏',class:'asia-bg',desc:'Companies across Asia'}};
  const $=s=>document.querySelector(s); let prices=null, chosen=null, toastTimer, cloudReady=false;
  const blank=()=>({version:2,modifiedAt:0,pinHash:'',pinSalt:'',pending:0,totalDeposited:0,lastDeposit:null,holdings:{gold:0,usa:0,asia:0},transactions:[],snapshots:[]});
  let state=load();
  function load(){try{return {...blank(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return blank()}}
  function save(){state.modifiedAt=Date.now();localStorage.setItem(KEY,JSON.stringify(state));if(cloudReady)saveCloud(state).catch(()=>setSyncStatus('Saved locally','offline'));}
  function setSyncStatus(text,kind=''){const el=$('#syncStatus');el.textContent=text;el.className=`sync-pill ${kind}`.trim()}
  const money=n=>new Intl.NumberFormat('en-MY',{style:'currency',currency:'MYR'}).format(Number(n)||0);
  const pct=n=>`${n>=0?'+':''}${n.toFixed(2)}%`;
  const dateText=d=>new Intl.DateTimeFormat('en-MY',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d));
  const myrPrice=id=>prices.assets[id].usd*prices.fxUsdMyr;
  const currentValue=id=>state.holdings[id]*myrPrice(id);
  const totalValue=()=>Object.keys(META).reduce((s,id)=>s+currentValue(id),0)+state.pending;
  async function hashPin(pin,salt){const data=new TextEncoder().encode(`${salt}:${pin}`);const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
  function randomSalt(){return [...crypto.getRandomValues(new Uint8Array(12))].map(b=>b.toString(16).padStart(2,'0')).join('')}
  async function getPrices(){try{const r=await fetch(`prices.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw 0;prices=await r.json();localStorage.setItem(`${KEY}-prices`,JSON.stringify(prices));}catch{prices=JSON.parse(localStorage.getItem(`${KEY}-prices`)||'null');}if(!prices){showToast('Prices are temporarily unavailable.');return}render()}
  function captureSnapshot(){if(!prices||!state.totalDeposited)return;const today=new Date().toISOString().slice(0,10);const point={date:today,value:+totalValue().toFixed(2),deposited:state.totalDeposited};const i=state.snapshots.findIndex(x=>x.date===today);if(i>=0&&state.snapshots[i].value===point.value&&state.snapshots[i].deposited===point.deposited)return;if(i>=0)state.snapshots[i]=point;else state.snapshots.push(point);state.snapshots=state.snapshots.slice(-180);save()}
  function render(){if(!prices)return;captureSnapshot();const total=totalValue(),gain=total-state.totalDeposited,ret=state.totalDeposited?gain/state.totalDeposited*100:0;$('#totalValue').textContent=money(total);$('#contributed').textContent=money(state.totalDeposited);$('#gainAmount').textContent=`${gain>=0?'+':''}${money(gain)}`;const gl=$('#gainLine');gl.textContent=state.totalDeposited?`${gain>=0?'Up':'Down'} ${money(Math.abs(gain))} (${pct(ret)}) since you started`:'Start with your first deposit';gl.className=`gain ${gain>0?'positive':gain<0?'negative':'neutral'}`;$('#choicePanel').classList.toggle('hidden',state.pending<=0);$('#choiceTitle').textContent=`Choose where your ${money(state.pending)} goes`;$('#readyAmount').textContent=`${money(state.pending)} ready`;renderAssets();renderHistory();drawChart();const asOf=new Date(prices.asOf);$('#priceNote').textContent=`Prices updated ${dateText(asOf)} · Values include USD to MYR exchange-rate movement.`}
  function renderAssets(){const choices=$('#choiceGrid'),holdings=$('#holdingsGrid');choices.innerHTML='';holdings.innerHTML='';Object.entries(META).forEach(([id,m])=>{const p=myrPrice(id),daily=(prices.assets[id].usd/prices.assets[id].previousUsd-1)*100;choices.insertAdjacentHTML('beforeend',`<button class="asset-card" data-invest="${id}"><span class="asset-top"><span class="asset-icon ${m.class}">${m.icon}</span><span class="asset-change ${daily>=0?'positive':'negative'}">${pct(daily)}</span></span><h3>${m.name}</h3><p>${m.desc}</p><span class="invest-label">Choose ${m.name} →</span></button>`);holdings.insertAdjacentHTML('beforeend',`<article class="asset-card holding-card"><span class="asset-icon ${m.class}">${m.icon}</span><h3>${m.name}</h3><p>${state.holdings[id]?state.holdings[id].toFixed(5)+' virtual units':'Nothing invested yet'}</p><strong class="asset-value">${money(currentValue(id))}</strong></article>`)});choices.querySelectorAll('[data-invest]').forEach(b=>b.onclick=()=>openConfirm(b.dataset.invest))}
  function renderHistory(){const box=$('#history');if(!state.transactions.length){box.innerHTML='<div class="empty-state">Your choices will appear here.</div>';return}box.innerHTML=[...state.transactions].reverse().map(t=>`<div class="history-item"><span class="history-icon">${META[t.asset].icon}</span><div class="history-main"><strong>Chose ${META[t.asset].name}</strong><span>${t.units.toFixed(5)} virtual units at ${money(t.priceMyr)}</span></div><span class="history-date">${dateText(t.date)}</span><span class="history-amount">${money(t.amount)}</span></div>`).join('')}
  function openConfirm(id){chosen=id;const m=META[id],amount=state.pending;$('#confirmIcon').textContent=m.icon;$('#confirmTitle').textContent=`Invest ${money(amount)} in ${m.name}?`;$('#confirmCopy').textContent=`At the latest price, this buys ${(amount/myrPrice(id)).toFixed(5)} virtual units.`;$('#confirmDialog').showModal()}
  function invest(id){if(state.pending<=0||!META[id]||!prices)throw new Error('No deposit is ready.');const amount=state.pending,price=myrPrice(id),units=amount/price;state.pending=0;state.holdings[id]+=units;state.transactions.push({id:crypto.randomUUID(),type:'buy',asset:id,amount,priceMyr:price,units,date:new Date().toISOString()});save();render();showToast(`🎉 ${money(amount)} invested in ${META[id].name}!`);return {asset:id,amount,units}}
  function canDeposit(){if(state.pending>0)return {ok:false,message:`The current ${money(state.pending)} still needs to be invested.`};if(!state.lastDeposit)return {ok:true,message:'Ready now'};const days=(Date.now()-new Date(state.lastDeposit))/864e5;return days>=6?{ok:true,message:'Ready now'}:{ok:false,message:`Ready in ${Math.ceil(6-days)} day${Math.ceil(6-days)===1?'':'s'}`}}
  function addDeposit(){const c=canDeposit();if(!c.ok)throw new Error(c.message);state.pending+=20;state.totalDeposited+=20;state.lastDeposit=new Date().toISOString();save();render();showToast('RM20 is ready to invest.');return {pending:state.pending,totalDeposited:state.totalDeposited}}
  function addCustomDeposit(amount){amount=Math.round(Number(amount)*100)/100;if(!Number.isFinite(amount)||amount<=0||amount>10000)throw new Error('Enter an amount from RM1 to RM10,000.');if(state.pending>0)throw new Error('Invest the money already waiting first.');state.pending=amount;state.totalDeposited+=amount;state.lastDeposit=new Date().toISOString();save();render();showToast(`${money(amount)} is ready to invest.`)}
  function undoLatestInvestment(){const t=state.transactions.at(-1);if(!t||t.type!=='buy')throw new Error('There is no investment to undo.');if(state.pending>0)throw new Error('Invest or reset the money already waiting first.');state.transactions.pop();state.holdings[t.asset]=Math.max(0,state.holdings[t.asset]-t.units);state.pending=t.amount;save();render();showToast(`${money(t.amount)} was returned ready to invest.`)}
  function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
  function openParent(){if(!state.pinHash)return $('#setupDialog').showModal();$('#parentPin').value='';$('#pinError').textContent='';$('#pinStep').classList.remove('hidden');$('#parentControls').classList.add('hidden');$('#parentDialog').showModal();setTimeout(()=>{$('#parentPin').value='';$('#parentPin').focus()},50)}
  function showParentControls(){const c=canDeposit();$('#pinStep').classList.add('hidden');$('#parentControls').classList.remove('hidden');$('#depositStatus').textContent=c.message;$('#depositButton').disabled=!c.ok;$('#parentTitle').textContent='Parent controls'}
  function drawChart(){const canvas=$('#journeyChart'),points=state.snapshots;$('#chartEmpty').classList.toggle('hidden',points.length>1);canvas.classList.toggle('hidden',points.length<2);if(points.length<2)return;const ratio=devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*ratio;canvas.height=h*ratio;const c=canvas.getContext('2d');c.scale(ratio,ratio);c.clearRect(0,0,w,h);const pad={l:10,r:10,t:16,b:24},max=Math.max(...points.flatMap(p=>[p.value,p.deposited]))*1.08,min=Math.min(0,...points.flatMap(p=>[p.value,p.deposited]))*.98,x=i=>pad.l+i*(w-pad.l-pad.r)/(points.length-1),y=v=>h-pad.b-(v-min)/(max-min||1)*(h-pad.t-pad.b);c.strokeStyle='#e3e8ef';c.lineWidth=1;[0,.5,1].forEach(f=>{const yy=pad.t+f*(h-pad.t-pad.b);c.beginPath();c.moveTo(pad.l,yy);c.lineTo(w-pad.r,yy);c.stroke()});function line(key,color,dash=[]){c.beginPath();points.forEach((p,i)=>i?c.lineTo(x(i),y(p[key])):c.moveTo(x(i),y(p[key])));c.strokeStyle=color;c.lineWidth=3;c.setLineDash(dash);c.lineJoin='round';c.lineCap='round';c.stroke()}line('deposited','#9ba8b8',[6,5]);line('value','#4b8fff');c.setLineDash([]);c.fillStyle='#66758a';c.font='12px sans-serif';c.fillText(dateText(points[0].date).replace(/ \d{4}/,''),pad.l,h-5);const end=dateText(points.at(-1).date).replace(/ \d{4}/,'');c.fillText(end,w-pad.r-c.measureText(end).width,h-5)}
  $('#setupForm').addEventListener('submit',async e=>{e.preventDefault();const a=$('#setupPin').value,b=$('#setupPinConfirm').value;if(!/^\d{4,8}$/.test(a)){return $('#setupError').textContent='Use 4–8 numbers.'}if(a!==b){return $('#setupError').textContent='The PINs do not match.'}state=blank();state.pinSalt=randomSalt();state.pinHash=await hashPin(a,state.pinSalt);state.pending=20;state.totalDeposited=20;state.lastDeposit=new Date().toISOString();save();$('#setupDialog').close();render();showToast('Your first RM20 is ready!')});
  $('#parentButton').onclick=openParent;$('#parentForm').addEventListener('submit',async e=>{e.preventDefault();if($('#parentControls').classList.contains('hidden')){const h=await hashPin($('#parentPin').value,state.pinSalt);if(h===state.pinHash)showParentControls();else $('#pinError').textContent='That PIN is not correct.'}});$('#depositButton').onclick=()=>{try{addDeposit();showParentControls()}catch(e){showToast(e.message)}};$('#confirmInvest').onclick=e=>{e.preventDefault();try{invest(chosen);$('#confirmDialog').close()}catch(err){showToast(err.message)}};$('#refreshButton').onclick=()=>{getPrices();showToast('Checking the latest prices…')};
  $('#customDepositButton').onclick=()=>{try{addCustomDeposit($('#customAmount').value);$('#customAmount').value='';showParentControls()}catch(e){showToast(e.message)}};
  $('#changePinButton').onclick=async()=>{const a=$('#newPin').value,b=$('#confirmNewPin').value;if(!/^\d{4,8}$/.test(a))return showToast('Use 4–8 numbers for the new PIN.');if(a!==b)return showToast('The new PINs do not match.');state.pinSalt=randomSalt();state.pinHash=await hashPin(a,state.pinSalt);$('#newPin').value='';$('#confirmNewPin').value='';save();showToast('Parent PIN changed.')};
  $('#undoButton').onclick=()=>{try{undoLatestInvestment()}catch(e){showToast(e.message)}};
  $('#openResetButton').onclick=()=>{$('#resetConfirmation').value='';$('#resetError').textContent='';$('#resetDialog').showModal()};
  $('#resetForm').addEventListener('submit',e=>{e.preventDefault();if($('#resetConfirmation').value!=='RESET')return $('#resetError').textContent='Type RESET exactly.';const pinHash=state.pinHash,pinSalt=state.pinSalt;state=blank();state.pinHash=pinHash;state.pinSalt=pinSalt;save();render();$('#resetDialog').close();$('#parentDialog').close();showToast('The account has been reset.')});
  $('#exportButton').onclick=()=>{const blob=new Blob([JSON.stringify({app:'my-investment-account',exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`investment-account-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)};
  $('#importInput').onchange=async e=>{try{const parsed=JSON.parse(await e.target.files[0].text());if(parsed.app!=='my-investment-account'||!parsed.data?.holdings)throw 0;state={...blank(),...parsed.data};save();render();$('#parentDialog').close();showToast('Backup restored.')}catch{showToast('That backup file is not valid.')}e.target.value=''};
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#setupDialog').open)e.preventDefault()});
  if(document.modelContext?.registerTool){const register=(tool)=>Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});register({name:'read_portfolio',title:'Read portfolio',description:'Read the current pretend investment portfolio without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({totalValue:totalValue(),totalDeposited:state.totalDeposited,pending:state.pending,holdings:state.holdings})});register({name:'invest_weekly_deposit',title:'Invest weekly deposit',description:'Invest the ready RM20 weekly deposit in gold, USA, or Asia.',inputSchema:{type:'object',properties:{asset:{type:'string',enum:['gold','usa','asia']}},required:['asset'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({asset})=>invest(asset)})}
  $('#authForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('#signInButton');$('#authError').textContent='';button.disabled=true;button.textContent='Signing in…';try{await signInCloud($('#authEmail').value.trim(),$('#authPassword').value);$('#authDialog').close()}catch(err){const messages={'auth/invalid-credential':'The email or password is incorrect.','auth/too-many-requests':'Too many attempts. Please wait and try again.','auth/network-request-failed':'No internet connection. Please try again.'};$('#authError').textContent=messages[err.code]||err.message||'Unable to sign in.'}finally{button.disabled=false;button.textContent='Sign in securely'}});
  $('#signOutButton').onclick=async()=>{await signOutCloud();cloudReady=false;$('#parentDialog').close();$('#authPassword').value='';$('#authDialog').showModal()};
  getPrices();
  startCloud({
    getLocalState:()=>state,
    onRemoteState:remote=>{const incoming={...blank(),...remote};if((incoming.modifiedAt||0)>(state.modifiedAt||0)){state=incoming;localStorage.setItem(KEY,JSON.stringify(state));render()}else if((state.modifiedAt||0)>(incoming.modifiedAt||0)&&cloudReady){saveCloud(state).catch(()=>setSyncStatus('Saved locally','offline'))}if(!state.pinHash&&!$('#setupDialog').open)$('#setupDialog').showModal()},
    onUser:user=>{cloudReady=!!user;if(user){if($('#authDialog').open)$('#authDialog').close()}else if(!$('#authDialog').open)$('#authDialog').showModal()},
    onStatus:setSyncStatus
  }).catch(err=>{setSyncStatus('Setup needed','offline');$('#authError').textContent=err.message;if(!$('#authDialog').open)$('#authDialog').showModal()});
})();
